(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sy*0.03+t*0.5)*8 + Math.cos(sx*0.025-t*0.4)*6;
  const w2y = Math.cos(sx*0.028-t*0.45)*8 + Math.sin(sy*0.022+t*0.55)*6;
  const dx = sx+w2x, dy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [60+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.6+2)*40, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.45+1)*60, 220+Math.sin(t*0.65+4)*50, 0.13, 1.8, 1.05]
  ];
  let aS=0, iS=0, hS=0;
  for(const[sX,sY,f,sp,w] of src){
    const d=Math.sqrt((dx-sX)**2+(dy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    hS+=Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.5;
  }
  const act=aS/8, inh=iS/8, harm=hS/8;
  const bg=(Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1))/2+Math.sin((dx+dy)*0.12+t*2.5)*0.2+Math.sin((dx-dy)*0.1-t*2)*0.2;
  const micro=Math.sin(dx*0.31+dy*0.27+t*1.8)*Math.sin(dx*0.23-dy*0.29-t*1.3)*Math.sin((dx*dy)*0.0001+t*0.7);
  const dist=Math.sqrt((dx-cx)**2+(dy-cy)**2), ang=Math.atan2(dy-cy,dx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=Math.sin(dist*0.08+ang*2-t*2.2)*Math.cos(dist*0.06-ang*5+t*1.8)*0.25;
  const waveFront=Math.sin(dist*0.12-t*3)*0.3*Math.exp(-dist*0.005);
  const reaction=Math.tanh((act-inh*0.65+harm*0.4+bg*0.3+spiral+spiral2+waveFront+micro*0.15)*2.0);
  const cell=Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5)*1.5)*0.3;
  const ridge=Math.abs(Math.sin(dx*0.08+t*0.4)*Math.cos(dy*0.09-t*0.5))<0.08?0.3:0;
  const contour=Math.abs(reaction%0.2)<0.015?0.15:0;
  const blend=reaction*0.6+cell*0.2+ridge+contour, v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,85],[18,90,105],[28,148,132],[80,185,120],[200,195,65],[225,140,55],[195,75,65],[130,35,72],[55,18,55],[5,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.3?1.05:0.95;
  const depth=0.9+dist*0.0005;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*depth)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*depth)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*depth)|0
  ];
}
